const b = $input.first().json.body;

if (!b || !b.email) throw new Error('Payload inválido: email ausente');

// Nome
const parts = (b.name || '').trim().split(' ');
const firstname = parts[0] || 'Lead';
const lastname = parts.slice(1).join(' ') || '';
const fullname = `${firstname}${lastname ? ' ' + lastname : ''}`;

// Mapeamento SUBTEMA (aprofundamento) → enum HubSpot tema
// Mais específico que o macro — usado como valor principal de `tema`
const SUBTEMA_MAP = {
  // Liderança
  'Alta Performance':       'Motivação',
  'Liderança Feminina':     'Protagonismo Feminino',
  'Gestão de Times':        'Gestão de Pessoas',
  'Inteligência Emocional': 'Comportamento',
  'Liderança Ágil':         'Liderança',
  'Cultura de Resultado':   'Liderança',
  // Vendas & Negócios
  'Negociação':             'Vendas',
  'Inside Sales':           'Vendas',
  'Customer Experience':    'Experiência e Atendimento ao Cliente',
  'Growth Hacking':         'Negócios',
  'Retail & Varejo':        'Negócios',
  'Precificação':           'Negócios',
  // Inovação & IA
  'IA & Machine Learning':  'Inovação',
  'Transformação Digital':  'Inovação',
  'Startups':               'Empreendedorismo',
  'Design Thinking':        'Inovação',
  'Future Skills':          'Outros',
  'Open Innovation':        'Inovação',
  // Marketing & Growth
  'Branding':               'Negócios',
  'Marketing Digital':      'Negócios',
  'Storytelling':           'Comunicação',
  'Data-Driven':            'Negócios',
  'Social Media':           'Comunicação',
  'Performance & ROI':      'Negócios',
  // Cultura & Pessoas
  'Diversidade & Inclusão': 'Diversidade',
  'Employer Branding':      'Gestão de Pessoas',
  'People Analytics':       'Gestão de Pessoas',
  'Engajamento':            'Gestão de Pessoas',
  'Retenção':               'Gestão de Pessoas',
  'Futuro do RH':           'Gestão de Pessoas',
  // ESG
  'ESG para Negócios':      'Sustentabilidade e Responsabilidade Social',
  'Impacto Social':         'Sustentabilidade e Responsabilidade Social',
  'Economia Circular':      'Sustentabilidade e Responsabilidade Social',
  'Governança':             'Sustentabilidade e Responsabilidade Social',
  'Clima & Energia':        'Sustentabilidade e Responsabilidade Social',
  'Diversidade & ESG':      'Diversidade',
  // Saúde & Bem-estar
  'Saúde Mental':           'Saúde',
  'Burnout & Resiliência':  'Saúde',
  'Mindfulness':            'Saúde',
  'Produtividade':          'Motivação',
  'Neurociência':           'Saúde',
  'Performance Humana':     'Saúde',
  // Futuro & Tendências
  'Megatendências':         'Outros',
  'Futuro do Trabalho':     'Outros',
  'Geração Z & Alpha':      'Outros',
  'Geopolítica':            'Política',
  'Cenários 2030+':         'Outros',
  'Nova Economia':          'Economia',
  // Outro
  'Educação':               'Educação',
  'Esporte & Superação':    'Esporte',
  'Criatividade':           'Outros',
  'Oratória':               'Comunicação',
  'Finanças':               'Finanças',
  'Outro':                  'Outros',
};

// Fallback: macro tema → enum HubSpot (caso subtema não encontrado)
const MACRO_MAP = {
  'Liderança':           'Liderança',
  'Vendas & Negócios':   'Vendas',
  'Inovação & IA':       'Inovação',
  'Marketing & Growth':  'Negócios',
  'Cultura & Pessoas':   'Gestão de Pessoas',
  'ESG & Sustentab.':    'Sustentabilidade e Responsabilidade Social',
  'Saúde & Bem-estar':   'Saúde',
  'Futuro & Tendências': 'Outros',
  'Outro tema':          'Outros',
};

// Mapeamento orçamento → enum HubSpot budget
const BUDGET_MAP = {
  'Até R$ 10 mil':       '6k à 10k',
  'Até R$ 50 mil':       '41k à 60k',
  'Até R$ 100 mil':      '+ de 80k',
  'Acima de R$ 100 mil': '+ de 80k',
};

// Mapeamento timing → data estimada (ms UTC)
const now = new Date();
const TIMING_DATE = {
  'Urgente (–30 dias)': new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() + 20)).getTime(),
  'Próximo mês':        new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() + 1, 15)).getTime(),
  '2º semestre 2026':   new Date(Date.UTC(2026, 9, 1)).getTime(),
  '2027 ou além':       new Date(Date.UTC(2027, 2, 1)).getTime(),
};

const temaHubspot = SUBTEMA_MAP[b.subtema] || MACRO_MAP[b.tema] || 'Outros';

return [{
  json: {
    firstname,
    lastname,
    email:           b.email.toLowerCase().trim(),
    phone:           (b.phone || '').replace(/\D/g, ''),
    tema:            temaHubspot,
    budget:          BUDGET_MAP[b.orcamento] || 'Não informado',
    data_do_evento:  TIMING_DATE[b.timing] || null,
    message:         [`Tema: ${b.tema || ''}`, `Aprofundamento: ${b.subtema || ''}`, `Audiência: ${b.audiencia || ''}`].filter(s => !s.endsWith(': ')).join(' | '),
    origem_do_lead:  'Inbound',
    hs_lead_status:  'NEW',
    lifecyclestage:  '1062353184',
    dealname:        `Curadoria Pocket · ${fullname} · ${b.subtema || b.tema || ''}`.trim(),
  }
}];
